 let unit='usd',availabilitySequence=0;
 async function loadAvailability(){
  const ticket=++availabilitySequence;
  try{
   const availability=await api('/pools/'+$('#bt-pool').value+'/backtest-availability?window='+$('#bt-window').value);
   if(ticket!==availabilitySequence||generation!==backtestGeneration)return;
   const suggestion=availability.suggestion;
   $('#bt-availability').innerHTML=suggestion?`Dữ liệu: ${availability.history_rows} quan sát · ${availability.missing_days} ngày trống. Đoạn liên tục được gợi ý: ${date(suggestion.start)} → ${date(suggestion.end)} (${suggestion.holding_days} ngày replay, warmup volatility ${suggestion.volatility_window_days} ngày). <button id="apply-available-window" type="button" class="btn small">Áp dụng khoảng liên tục${suggestion.window_changed?' & warmup '+suggestion.volatility_window_days+'N':''}</button>`:esc(availability.reason);
   if(suggestion)$('#apply-available-window').onclick=()=>{if($('#run-backtest').disabled)return;
    $('#bt-start').value=suggestion.start;$('#bt-end').value=suggestion.end;$('#bt-window').value=suggestion.volatility_window_days;read();
    $('#bt-status').textContent='Đã áp dụng đoạn liên tục · cần chạy lại';['export-csv','export-full-csv'].forEach(id=>$('#'+id).disabled=true);
    toast('Đã chọn theo lịch dữ liệu; không dùng lợi nhuận để chọn khoảng.');
   };
  }catch(e){if(ticket===availabilitySequence&&generation===backtestGeneration)$('#bt-availability').textContent=errorText(e);}
 }
