 function syncDraft(){const selected=presetFor(form);$('#bt-preset').value=selected;$('#bt-settings-summary').textContent=(selected==='custom'?'Tham số tùy chỉnh':presets[selected].label)+': w cố định '+num(form.half_width)+' log, cửa sổ '+form.volatility_window_days+' ngày. '+(form.strategy_mode==='research'?'Khoảng động chỉ dời khi ra ngoài; độ rộng theo biến động giữ tại entry.':'Khoảng động và độ rộng theo biến động cập nhật hằng tuần.')+(lastComparison?' Kết quả bên dưới giữ nguyên cấu hình đã chạy; bấm chạy lại để áp dụng thay đổi.':'');if(!lastComparison)Object.keys(labels).forEach(id=>{labels[id]=researchView.strategyLabel(id,form);const card=$('[data-strategy="'+id+'"]').closest('label');$('strong',card).textContent=labels[id];$('p',card).textContent=researchView.strategyDescription(id,form);});}
 $('#bt-strategy-mode').value=form.strategy_mode;syncDraft();
 $('#bt-preset').onchange=()=>{const selected=$('#bt-preset').value;if(!presets[selected])return;comparisonRequest++;form={...form,...presets[selected].config};const fields={'bt-capital':'capital','bt-gas':'gas_usd','bt-width':'half_width','bt-window':'volatility_window_days','bt-slippage':'rebalance_slippage_bps','bt-concentration':'concentration','bt-protocol':'protocol_fee_fraction','bt-max-rebalances':'max_rebalances','bt-gap':'min_rebalance_gap_days','bt-risk':'risk_max_exit_prob','bt-seed':'seed','bt-price-source':'price_source','bt-strategy-mode':'strategy_mode'};for(const [id,key] of Object.entries(fields))$('#'+id).value=['protocol_fee_fraction','risk_max_exit_prob'].includes(key)?form[key]*100:form[key];$('#bt-partial').checked=form.allow_partial;save('backtest',form);syncDraft();loadAvailability();$('#bt-status').textContent='Đã chọn bộ cấu hình · cần chạy lại';['export-csv','export-full-csv'].forEach(id=>$('#'+id).disabled=true);};
 function read(){form={...form,strategy_mode:$('#bt-strategy-mode').value,pool:$('#bt-pool').value,start:$('#bt-start').value,end:$('#bt-end').value,capital:Number($('#bt-capital').value),gas_usd:Number($('#bt-gas').value),half_width:Number($('#bt-width').value),volatility_window_days:Number($('#bt-window').value),rebalance_slippage_bps:Number($('#bt-slippage').value),concentration:Number($('#bt-concentration').value),protocol_fee_fraction:Number($('#bt-protocol').value)/100,max_rebalances:Number($('#bt-max-rebalances').value),min_rebalance_gap_days:Number($('#bt-gap').value),risk_max_exit_prob:Number($('#bt-risk').value)/100,seed:Number($('#bt-seed').value),price_source:$('#bt-price-source').value,allow_partial:$('#bt-partial').checked};save('backtest',form);syncDraft();}
