 async function run(){read();const ticket=++comparisonRequest;await busy($('#run-backtest'),async()=>{const controls=$$('input.control,select.control,#bt-partial,#bt-reset,#apply-available-window',content),states=controls.map(el=>el.disabled);controls.forEach(el=>el.disabled=true);try{if(form.start>=form.end)throw new Error('Ngày bắt đầu phải trước ngày kết thúc.');const result=await api('/backtests/compare',{...form,strategies:['full','fixed','vol_scaled','dynamic','optimizer','hodl']});if(ticket!==comparisonRequest||generation!==backtestGeneration)return;save('lastComparison',result.meta.run_id);render(result);}finally{controls.forEach((el,i)=>el.disabled=states[i]);}},'Đang tái hiện lịch sử…');}
